/*\ TaxiTracker startup module v6 \*/
exports.name = 'taxitracker-startup';
exports.after = ['rootwidget'];
exports.platforms = ['browser'];
exports.synchronous = true;

exports.startup = function() {

  function fmt(n) { return parseFloat(n||0).toFixed(2); }

  function localDate(d) {
    d = d||new Date();
    return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
  }
  function todayPrefix()     { return localDate(); }
  function yesterdayPrefix() { var d=new Date(); d.setDate(d.getDate()-1); return localDate(d); }
  function nowId() {
    var d=new Date();
    return localDate(d)+' '+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')+':'+String(d.getSeconds()).padStart(2,'0');
  }
  function nowTime() {
    var d=new Date();
    return String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');
  }
  function isoWeek(date) {
    var d=date?new Date(date):new Date();
    d.setHours(0,0,0,0);
    d.setDate(d.getDate()+3-(d.getDay()+6)%7);
    var w1=new Date(d.getFullYear(),0,4);
    return 1+Math.round(((d.getTime()-w1.getTime())/86400000-3+(w1.getDay()+6)%7)/7);
  }
  function isoWeekYear(date) {
    var d=date?new Date(date+'T00:00:00'):new Date();
    d.setHours(0,0,0,0);
    d.setDate(d.getDate()+3-(d.getDay()+6)%7);
    return d.getFullYear();
  }
  function weekTag(date) {
    var d=date?new Date(date+'T00:00:00'):new Date();
    return 'week_'+isoWeek(d);
  }
  function shiftTag(sd) { return 'shift_'+sd; }

  function getConfig(key,def) { return ($tw.wiki.getTiddlerText('$:/taxitracker/'+key,'')||def||'').trim(); }
  function setConfig(key,val) {
    $tw.wiki.addTiddler(new $tw.Tiddler({title:'$:/taxitracker/'+key,text:String(val)}));
  }
  function getActiveShiftDate() { return getConfig('active-shift-date',''); }
  function setActiveShiftDate(d) { setConfig('active-shift-date',d); }
  function clearActiveShiftDate() { setConfig('active-shift-date',''); }

  function saveTiddler(fields) {
    $tw.wiki.addTiddler(new $tw.Tiddler(
      $tw.wiki.getCreationFields(),
      $tw.wiki.getModificationFields(),
      fields
    ));
  }
  function getTiddler(title) { var t=$tw.wiki.getTiddler(title); return t?t.fields:null; }
  function getAllTagged(tag) {
    return $tw.wiki.filterTiddlers('[tag['+tag+']]').map(function(title){
      return $tw.wiki.getTiddler(title).fields;
    });
  }

  function sendToTelegram(text) {
    var token=getConfig('tg-token','');
    var chatId=getConfig('tg-chatid','5899420190');
    if(!token){console.warn('TaxiTracker: TG_TOKEN not set');return;}
    fetch('https://api.telegram.org/bot'+token+'/sendMessage',{
      method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({chat_id:chatId,text:text,parse_mode:'HTML'})
    }).catch(function(e){console.warn('Telegram error:',e.message);});
  }

  function fmtTxnMsg(f) {
    var nl='\n';
    var splitLine='';
    if(f.split==='yes'){
      var parts=[];
      [['split-1-type','split-1-amount'],['split-2-type','split-2-amount'],['split-3-type','split-3-amount']].forEach(function(k){
        if(f[k[0]]) parts.push(f[k[0]]+' £'+fmt(f[k[1]]||0));
      });
      if(parts.length) splitLine=nl+'Split: '+parts.join(' + ');
    }
    return '<b>TXN</b> '+f.title+nl+
      (f.split==='yes'?'Split':f.payment)+' · Meter: £'+fmt(f.meter)+' · Charge: £'+fmt(f.charge)+' · Overring: £'+fmt(f.overring)+
      splitLine+nl+
      'Cash In: £'+fmt(f.cashin)+' · Gratuity: £'+fmt(f.gratuity)+
      (parseFloat(f.fees)>0?nl+'Fees: £'+fmt(f.fees):'')+
      (f.notes?nl+'Notes: '+f.notes:'');
  }

  function fmtShiftMsg(f) {
    var nl='\n';
    return '<b>SHIFT '+String(f['shift-type']).toUpperCase()+'</b> '+f['shift-date']+nl+'Time: '+f['shift-time']+' · Car: '+(f.car||'—')+nl+'R1: '+f.r1+'  R2: '+f.r2+'  R3: '+f.r3+'  R4: '+f.r4;
  }

  function clearScratch() {
    ['payment','meter','charge','overring','cashin','gratuity','fees',
     'split-mode','split-1-type','split-1-amount','split-2-type','split-2-amount',
     'split-3-type','split-3-amount'].forEach(function(f){
      $tw.wiki.addTiddler(new $tw.Tiddler({title:'$:/taxitracker/scratch/'+f, text:''}));
    });
    $tw.wiki.addTiddler(new $tw.Tiddler({title:'$:/taxitracker/state/meter-display', text:''}));
    $tw.wiki.addTiddler(new $tw.Tiddler({title:'$:/taxitracker/scratch/txn-time', text:nowTime()}));
    $tw.wiki.addTiddler(new $tw.Tiddler({title:'$:/taxitracker/scratch/notes', text:'FD '}));
    $tw.wiki.addTiddler(new $tw.Tiddler({title:'$:/taxitracker/state/split-balance', text:'0.00'}));
  }

  function calcFromMeter(meterStr) {
    var meter=parseFloat(meterStr)||0;
    var charge=Math.floor(meter*10)/10;
    var overring=parseFloat((meter-charge).toFixed(2));
    return {meter:meter,charge:charge,overring:overring,cashin:charge,gratuity:0};
  }

  function calcSummary(shiftDate) {
    var sDate=shiftDate||getActiveShiftDate()||todayPrefix();
    var tag=shiftTag(sDate);
    var txns=$tw.wiki.filterTiddlers('[tag[Transaction]tag['+tag+']]').map(function(title){
      var t=$tw.wiki.getTiddler(title); return t?t.fields:null;
    }).filter(Boolean);
    var cash=0,card=0,acct=0,cashGrat=0,cardGrat=0,over=0;
    txns.forEach(function(r){
      var ch=parseFloat(r.charge)||0, gr=parseFloat(r.gratuity)||0, or=parseFloat(r.overring)||0;
      over+=or;
      if(r.split==='yes'){
        var hasCash=false,hasCard=false;
        [['split-1-type','split-1-amount'],['split-2-type','split-2-amount'],['split-3-type','split-3-amount']].forEach(function(keys){
          var t=r[keys[0]],a=parseFloat(r[keys[1]])||0;
          if(!t||!a) return;
          if(t==='Cash'){cash+=a;hasCash=true;}
          if(t==='Card'){card+=a;hasCard=true;}
          if(t==='Account') acct+=a;
        });
        if(hasCash) cashGrat+=gr; else if(hasCard) cardGrat+=gr;
      } else {
        if(r.payment==='Cash')   {cash+=ch;cashGrat+=gr;}
        if(r.payment==='Card')   {card+=ch;cardGrat+=gr;}
        if(r.payment==='Account') acct+=ch;
      }
    });
    var total=cash+card+acct;
    return {count:txns.length,txns:txns,cash:cash,card:card,acct:acct,ca:card+acct,total:total,over:over,cashGrat:cashGrat,cardGrat:cardGrat,driver:total*0.45+cardGrat};
  }

  function journalWrite(fields) {
    try {
      var j=JSON.parse(localStorage.getItem('tt_journal')||'[]');
      j.push(fields);
      if(j.length>500) j=j.slice(-500);
      localStorage.setItem('tt_journal',JSON.stringify(j));
    } catch(e){}
  }

  function journalReconcile() {
    try {
      var j=JSON.parse(localStorage.getItem('tt_journal')||'[]');
      var missing=j.filter(function(f){return f.title&&!$tw.wiki.getTiddler(f.title);});
      $tw.wiki.addTiddler(new $tw.Tiddler({
        title:'$:/taxitracker/state/journal-orphans',
        text:JSON.stringify(missing),
        count:String(missing.length)
      }));
    } catch(e){}
  }

  function sendCheckpoint(shiftDate) {
    var s=calcSummary(shiftDate);
    sendToTelegram('CHECKPOINT::'+JSON.stringify({
      exportDate:shiftDate,
      exportTime:new Date().toISOString(),
      txnCount:s.count,
      transactions:s.txns
    }));
  }

  function downloadBackup(shiftDate) {
    var s=calcSummary(shiftDate);
    var data=JSON.stringify({exportDate:shiftDate,exportTime:new Date().toISOString(),transactions:s.txns},null,2);
    try {
      var blob=new Blob([data],{type:'application/json'});
      var url=URL.createObjectURL(blob);
      var a=document.createElement('a');
      a.href=url; a.download='tt-backup-'+shiftDate+'.json';
      document.body.appendChild(a); a.click();
      document.body.removeChild(a); URL.revokeObjectURL(url);
    } catch(e){console.warn('TaxiTracker: download backup failed',e);}
  }

  var _wakeLock=null;
  var _wakeLockPending=false;

  function acquireWakeLock() {
    if(!('wakeLock' in navigator)||_wakeLockPending||_wakeLock) return;
    _wakeLockPending=true;
    navigator.wakeLock.request('screen').then(function(wl){
      _wakeLock=wl;
      _wakeLockPending=false;
      setConfig('state/wakelock','active');
      wl.addEventListener('release',function(){_wakeLock=null;setConfig('state/wakelock','');});
    }).catch(function(e){
      _wakeLockPending=false;
      console.warn('TaxiTracker: wake lock failed',e.message);
    });
  }

  function releaseWakeLock() {
    if(_wakeLock){_wakeLock.release();_wakeLock=null;}
    setConfig('state/wakelock','');
  }

  document.addEventListener('visibilitychange',function(){
    if(document.visibilityState==='visible'&&getActiveShiftDate()&&!_wakeLock) acquireWakeLock();
  });

  window.TaxiTracker = {

    todayPrefix:todayPrefix, yesterdayPrefix:yesterdayPrefix,
    nowId:nowId, nowTime:nowTime, fmt:fmt,
    getActiveShiftDate:getActiveShiftDate,
    isoWeek:isoWeek, isoWeekYear:isoWeekYear,
    calcFromMeter:calcFromMeter, clearScratch:clearScratch,
    calcSummary:calcSummary, journalReconcile:journalReconcile,
    downloadBackup:downloadBackup,

    recordTxn: function() {
      var payment = getConfig('scratch/payment','');
      var meter   = getConfig('scratch/meter','');
      var charge  = getConfig('scratch/charge','');
      var overring= getConfig('scratch/overring','');
      var cashin  = getConfig('scratch/cashin','');
      var gratuity= getConfig('scratch/gratuity','');
      var notes   = getConfig('scratch/notes','');
      var fees    = getConfig('scratch/fees','');
      var txnTime = getConfig('scratch/txn-time','');
      var splitMode = getConfig('scratch/split-mode','');
      if(!meter) return {ok:false,msg:'Enter meter reading'};
      var id=nowId();
      var shiftDate=getActiveShiftDate()||todayPrefix();
      var wk=weekTag(shiftDate);
      var sTag=shiftTag(shiftDate);
      var fields={
        title:id, tags:'Transaction '+sTag+' '+wk,
        'txn-date':shiftDate, 'txn-time':txnTime||id.split(' ')[1],
        payment:payment,
        meter:String(parseInt(meter,10)/100||0),
        charge:String(parseFloat(charge)||0),
        overring:String(parseFloat(overring)||0),
        cashin:String(parseFloat(cashin)||0),
        gratuity:String(parseFloat(gratuity)||0),
        fees:String(parseFloat(fees)||0),
        notes:String(notes).trim(),
        split:splitMode
      };
      if(splitMode==='yes'){
        var s1t=getConfig('scratch/split-1-type',''), s1a=getConfig('scratch/split-1-amount','');
        var s2t=getConfig('scratch/split-2-type',''), s2a=getConfig('scratch/split-2-amount','');
        var s3t=getConfig('scratch/split-3-type',''), s3a=getConfig('scratch/split-3-amount','');
        if(!s1t||!s2t) return {ok:false,msg:'Select payment type for both split rows'};
        fields['split-1-type']=s1t; fields['split-1-amount']=String(parseFloat(s1a)||0);
        fields['split-2-type']=s2t; fields['split-2-amount']=String(parseFloat(s2a)||0);
        fields['split-3-type']=s3t; fields['split-3-amount']=String(parseFloat(s3a)||0);
        fields.payment='Split';
        var cashPortion=0;
        [[s1t,s1a],[s2t,s2a],[s3t,s3a]].forEach(function(p){if(p[0]==='Cash')cashPortion+=parseFloat(p[1])||0;});
        fields.cashin=String(cashPortion+(parseFloat(gratuity)||0));
      } else {
        if(!payment) return {ok:false,msg:'Select a payment type'};
      }
      saveTiddler(fields);
      journalWrite(fields);
      sendToTelegram(fmtTxnMsg(getTiddler(id)));
      clearScratch();
      $tw.rootWidget.dispatchEvent({type:'tm-auto-save-wiki'});
      var cnt=$tw.wiki.filterTiddlers('[tag[Transaction]tag['+sTag+']]').length;
      setConfig('state/txn-count',String(cnt));
      if(cnt>0&&cnt%5===0) sendCheckpoint(shiftDate);
      return {ok:true,id:id};
    },

    getTxnsForShift: function(shiftDate) {
      var sDate=shiftDate||getActiveShiftDate()||todayPrefix();
      var tag=shiftTag(sDate);
      return $tw.wiki.filterTiddlers('[tag[Transaction]tag['+tag+']]').map(function(title){
        var t=$tw.wiki.getTiddler(title); return t?t.fields:null;
      }).filter(Boolean).sort(function(a,b){return a.title<b.title?-1:1;});
    },

    getTxn: function(id) { return getTiddler(id); },

    saveShift: function(type,time,car,r1,r2,r3,r4) {
      if(!time) return {ok:false,msg:'Enter time'};
      var today=todayPrefix();
      var date=today;
      if(type==='Start') {
        setActiveShiftDate(today);
        date=today;
        acquireWakeLock();
      } else {
        var active=getActiveShiftDate();
        date=active||today;
      }
      var wk=weekTag(date);
      var title='Shift '+type+' '+date;
      var fields={
        title:title, tags:'Shift '+wk,
        'shift-date':date, 'shift-type':type, 'shift-time':time,
        car:String(car||''),
        r1:String(parseFloat(r1)||0), r2:String(parseFloat(r2)||0),
        r3:String(parseFloat(r3)||0), r4:String(parseFloat(r4)||0)
      };
      saveTiddler(fields);
      sendToTelegram(fmtShiftMsg(fields));
      $tw.rootWidget.dispatchEvent({type:'tm-auto-save-wiki'});
      return {ok:true,date:date};
    },

    getShift: function(type) {
      var active=getActiveShiftDate();
      var today=todayPrefix();
      var yest=yesterdayPrefix();
      return getAllTagged('Shift').find(function(r){
        return r['shift-type']===type&&(r['shift-date']===today||r['shift-date']===yest||(active&&r['shift-date']===active));
      })||null;
    },

    hasActiveShift: function() { return !!getActiveShiftDate(); },

    closeShift: function() {
      clearActiveShiftDate();
      releaseWakeLock();
      $tw.rootWidget.dispatchEvent({type:'tm-auto-save-wiki'});
      return {ok:true};
    },

    endShift: function() {
      var shiftDate=getActiveShiftDate()||todayPrefix();
      var s=calcSummary(shiftDate);
      var txns=s.txns;
      if(txns.length===0) return {ok:false,msg:'No transactions to send'};
      var shifts=getAllTagged('Shift').filter(function(r){
        return r['shift-date']===shiftDate||r['shift-date']===yesterdayPrefix();
      });
      var startR=shifts.find(function(r){return r['shift-type']==='Start';});
      var endR  =shifts.find(function(r){return r['shift-type']==='End';});
      var wk=weekTag(shiftDate);
      var DAYS=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
      var dayName=DAYS[new Date(shiftDate+'T00:00:00').getDay()];
      var r1c=startR&&endR?(parseFloat(endR.r1)-parseFloat(startR.r1)).toFixed(2):'—';
      var r2c=startR&&endR?(parseFloat(endR.r2)-parseFloat(startR.r2)).toFixed(2):'—';
      var r3c=startR&&endR?(parseFloat(endR.r3)-parseFloat(startR.r3)).toFixed(2):'—';
      var r4c=startR&&endR?(parseFloat(endR.r4)-parseFloat(startR.r4)).toFixed(2):'—';
      var meterTotal=txns.reduce(function(acc,t){return acc+(parseFloat(t.meter)||0);},0);
      var feesTotal=txns.reduce(function(acc,t){return acc+(parseFloat(t.fees)||0);},0);
      var fdList=txns.filter(function(t){return t.payment==='Account'&&t.notes&&t.notes.toUpperCase().indexOf('FD ')===0;}).map(function(t){return '* '+t.notes;});
      var cardList=txns.filter(function(t){
        if(t.payment==='Card') return true;
        if(t.split==='yes'&&[t['split-1-type'],t['split-2-type'],t['split-3-type']].indexOf('Card')>=0) return true;
        return false;
      }).map(function(t){var l='* £'+fmt(t.charge);if(parseFloat(t.gratuity)>0)l+=' - £'+fmt(t.gratuity)+' tip';return l;});
      var acctList=txns.filter(function(t){return t.payment==='Account';}).map(function(t){return '* £'+fmt(t.charge);});
      var cashEnclosed=s.cash-s.cardGrat;
      var nl='\n';
      var dsLines=[
        '!! '+dayName+' '+shiftDate,'',
        '; Shift Start',': '+(startR?startR['shift-time']:'—')+(startR&&startR.car?'  |  Car: '+startR.car:''),
        '; Shift End',  ': '+(endR?endR['shift-time']:'—'),'',
        '|!|!Start|!End|!Change|',
        '|R1|'+(startR?startR.r1:'—')+'|'+(endR?endR.r1:'—')+'|'+r1c+'|',
        '|R2|'+(startR?startR.r2:'—')+'|'+(endR?endR.r2:'—')+'|'+r2c+'|',
        '|R3|'+(startR?startR.r3:'—')+'|'+(endR?endR.r3:'—')+'|'+r3c+'|',
        '|R4|'+(startR?startR.r4:'—')+'|'+(endR?endR.r4:'—')+'|'+r4c+'|','',
        '; Meter Total',': £'+fmt(meterTotal),
        '; Overrings Total',': £'+fmt(s.over),
        '; Charge Total (Card + Account)',': £'+fmt(s.ca),
        "; Driver's Share (45%)",': £'+fmt(s.driver),
        '; Cash Enclosed',': £'+fmt(s.cash)+' - £'+fmt(s.cardGrat)+' = £'+fmt(cashEnclosed),
        '; Total Fees',': £'+fmt(feesTotal),
        ''
      ];
      if(fdList.length>0){dsLines.push('!! Food Delivery Addresses');dsLines=dsLines.concat(fdList);dsLines.push('');}
      if(cardList.length>0){dsLines.push('!! Card Charges');dsLines=dsLines.concat(cardList);dsLines.push('');}
      if(acctList.length>0){dsLines.push('!! Account Charges');dsLines=dsLines.concat(acctList);dsLines.push('');}
      saveTiddler({
        title:'Daily Sheet '+shiftDate, tags:'DailySheet '+wk,
        'sheet-date':shiftDate, 'shift-start':startR?startR['shift-time']:'', 'shift-end':endR?endR['shift-time']:'',
        'day-name':dayName, 'meter-total':fmt(meterTotal), 'over-total':fmt(s.over),
        'ca-total':fmt(s.ca), 'charge-total':fmt(s.total), 'driver-share':fmt(s.driver),
        'cash-total':fmt(s.cash), 'card-grat':fmt(s.cardGrat), 'cash-enclosed':fmt(cashEnclosed),
        'txn-count':String(s.count), text:dsLines.join(nl)
      });
      var stLines=['!! Transactions — '+dayName+' '+shiftDate,'','|!Date-Time|!Type|!Meter|!Charge|!Overring|!Cash In|!Gratuity|!Fees|!Notes|'];
      txns.forEach(function(t){
        var payStr=t.split==='yes'?
          [['split-1-type','split-1-amount'],['split-2-type','split-2-amount'],['split-3-type','split-3-amount']]
            .filter(function(k){return t[k[0]];}).map(function(k){return t[k[0]]+' £'+fmt(t[k[1]]||0);}).join('+'):
          t.payment;
        stLines.push('|'+t['txn-date']+' '+t['txn-time']+'|'+payStr+'|£'+fmt(t.meter)+'|£'+fmt(t.charge)+'|£'+fmt(t.overring)+'|£'+fmt(t.cashin)+'|£'+fmt(t.gratuity)+'|£'+fmt(t.fees||0)+'|'+(t.notes||'')+'|');
      });
      stLines.push('');
      var csvRows=['Date-Time,Type,Meter,Charge,Overring,Cash In,Gratuity,Fees,Notes'];
      txns.forEach(function(t){
        var payStr=t.split==='yes'?
          [['split-1-type','split-1-amount'],['split-2-type','split-2-amount'],['split-3-type','split-3-amount']]
            .filter(function(k){return t[k[0]];}).map(function(k){return t[k[0]]+' '+fmt(t[k[1]]||0);}).join('+'):
          t.payment;
        csvRows.push([t['txn-date']+' '+t['txn-time'],payStr,fmt(t.meter),fmt(t.charge),fmt(t.overring),fmt(t.cashin),fmt(t.gratuity),fmt(t.fees||0),'"'+(t.notes||'').replace(/"/g,'""')+'"'].join(','));
      });
      stLines.push('```');stLines=stLines.concat(csvRows);stLines.push('```');
      saveTiddler({title:'Shift '+shiftDate,tags:'ShiftTransactions '+wk,'shift-date':shiftDate,text:stLines.join(nl)});
      var summary={transactions:s.count,cash:+fmt(s.cash),card:+fmt(s.card),account:+fmt(s.acct),caTotal:+fmt(s.ca),totalCharge:+fmt(s.total),totalOverring:+fmt(s.over),cashGratuity:+fmt(s.cashGrat),cardGratuity:+fmt(s.cardGrat),driverShare:+fmt(s.driver)};
      sendToTelegram('ENDSHIFT::'+JSON.stringify({exportDate:shiftDate,exportTime:new Date().toISOString(),summary:summary,transactions:txns,shiftTotals:shifts}));
      releaseWakeLock();
      downloadBackup(shiftDate);
      $tw.rootWidget.dispatchEvent({type:'tm-auto-save-wiki'});
      return {ok:true};
    },

    freezeInvoice: function(weekNum,weekYr) {
      var wTag='week_'+weekNum;
      var sheets=getAllTagged('DailySheet').filter(function(r){
        return $tw.wiki.filterTiddlers('[title['+r.title+']tag['+wTag+']]').length>0;
      }).sort(function(a,b){return a['sheet-date']<b['sheet-date']?-1:1;});
      if(sheets.length===0) return {ok:false,msg:'No daily sheets found for week '+weekNum};
      var existingVersions=$tw.wiki.filterTiddlers('[prefix[Invoice Week '+weekNum+' '+weekYr+' v]]');
      var nextV=existingVersions.length+1;
      var frozenTitle='Invoice Week '+weekNum+' '+weekYr+' v'+nextV;
      var totalCharge=sheets.reduce(function(acc,r){return acc+(parseFloat(r['charge-total'])||0);},0);
      var totalDriver=sheets.reduce(function(acc,r){return acc+(parseFloat(r['driver-share'])||0);},0);
      var nl='\n';
      var frozenDate=new Date().toISOString().slice(0,10);
      var lines=[
        '!! Invoice Week '+weekNum+' '+weekYr+' — Version '+nextV,
        "''Frozen: '' "+frozenDate,'',
        "|!Shift Date|!Charge Total|!Driver's Share|"
      ];
      sheets.forEach(function(r){
        lines.push('|'+(r['day-name']||'')+' '+r['sheet-date']+'|£'+fmt(r['charge-total'])+'|£'+fmt(r['driver-share'])+'|');
      });
      lines.push("|''Total''|''£"+fmt(totalCharge)+"''|''£"+fmt(totalDriver)+"''|");
      saveTiddler({
        title:frozenTitle, tags:'FrozenInvoice '+wTag,
        week:String(weekNum), year:String(weekYr), version:String(nextV),
        'frozen-date':frozenDate,
        'total-charge':fmt(totalCharge), 'total-driver':fmt(totalDriver),
        text:lines.join(nl)
      });
      $tw.rootWidget.dispatchEvent({type:'tm-auto-save-wiki'});
      return {ok:true,title:frozenTitle,version:nextV};
    },

    updateTxn: function(title) {
      var t = $tw.wiki.getTiddler(title);
      if (!t) return {ok:false, msg:'Transaction not found'};
      var meter = getConfig('scratch/meter','');
      if (!meter) return {ok:false, msg:'Enter meter reading'};
      var payment  = getConfig('scratch/payment','');
      var charge   = getConfig('scratch/charge','');
      var overring = getConfig('scratch/overring','');
      var cashin   = getConfig('scratch/cashin','');
      var gratuity = getConfig('scratch/gratuity','');
      var fees     = getConfig('scratch/fees','');
      var notes    = getConfig('scratch/notes','');
      var txnTime  = getConfig('scratch/txn-time','');
      var splitMode= getConfig('scratch/split-mode','');
      var fields = {
        title: title,
        tags: t.fields.tags.join ? t.fields.tags.join(' ') : String(t.fields.tags),
        'txn-date':  t.fields['txn-date'],
        'txn-time':  txnTime || t.fields['txn-time'],
        payment: payment,
        meter:   String(parseInt(meter,10)/100||0),
        charge:  String(parseFloat(charge)||0),
        overring:String(parseFloat(overring)||0),
        cashin:  String(parseFloat(cashin)||0),
        gratuity:String(parseFloat(gratuity)||0),
        fees:    String(parseFloat(fees)||0),
        notes:   String(notes).trim(),
        split:   splitMode,
        'split-1-type':'','split-1-amount':'',
        'split-2-type':'','split-2-amount':'',
        'split-3-type':'','split-3-amount':''
      };
      if (splitMode === 'yes') {
        var s1t=getConfig('scratch/split-1-type',''), s1a=getConfig('scratch/split-1-amount','');
        var s2t=getConfig('scratch/split-2-type',''), s2a=getConfig('scratch/split-2-amount','');
        var s3t=getConfig('scratch/split-3-type',''), s3a=getConfig('scratch/split-3-amount','');
        if (!s1t||!s2t) return {ok:false, msg:'Select payment type for both split rows'};
        fields['split-1-type']=s1t; fields['split-1-amount']=String(parseFloat(s1a)||0);
        fields['split-2-type']=s2t; fields['split-2-amount']=String(parseFloat(s2a)||0);
        fields['split-3-type']=s3t; fields['split-3-amount']=String(parseFloat(s3a)||0);
        fields.payment='Split';
        var cp=0;
        [[s1t,s1a],[s2t,s2a],[s3t,s3a]].forEach(function(p){if(p[0]==='Cash')cp+=parseFloat(p[1])||0;});
        fields.cashin=String(cp+(parseFloat(gratuity)||0));
      } else {
        if (!payment) return {ok:false, msg:'Select a payment type'};
      }
      saveTiddler(fields);
      sendToTelegram('EDIT - ' + fmtTxnMsg(getTiddler(title)));
      clearScratch();
      $tw.rootWidget.dispatchEvent({type:'tm-auto-save-wiki'});
      return {ok:true};
    }

  }; // end window.TaxiTracker

}; // end exports.startup
